import sys, itertools, subprocess, random

# ---------- Grapheme / Literal ----------
class G:
    def __init__(self, chars, mn=1, mx=1):
        self.chars = chars; self.mn = mn; self.mx = mx
    def __eq__(self, o): return isinstance(o, G) and self.chars == o.chars and self.mn == o.mn and self.mx == o.mx
    def clone(self): return G(self.chars, self.mn, self.mx)
    def __repr__(self):
        s = self.chars
        if self.mn == self.mx == 1: return s
        if len(s) > 1: s = "(?:" + s + ")"
        if self.mn == self.mx: return s + "{%d}" % self.mn
        return s + "{%d,%d}" % (self.mn, self.mx)

class Lit:
    def __init__(self, gs): self.gs = gs
    def __eq__(self, o): return isinstance(o, Lit) and self.gs == o.gs
    def is_empty(self): return len(self.gs) == 0
    def clone(self): return Lit([g.clone() for g in self.gs])
class Alt:
    def __init__(self, opts): self.opts = opts
    def __eq__(self, o): return isinstance(o, Alt) and self.opts == o.opts
    def is_empty(self): return False
    def clone(self): return Alt([o.clone() for o in self.opts])
class Cat:
    def __init__(self, a, b): self.a = a; self.b = b
    def __eq__(self, o): return isinstance(o, Cat) and self.a == o.a and self.b == o.b
    def is_empty(self): return False
    def clone(self): return Cat(self.a.clone(), self.b.clone())
class Rep:
    def __init__(self, e, q): self.e = e; self.q = q
    def __eq__(self, o): return isinstance(o, Rep) and self.e == o.e and self.q == o.q
    def is_empty(self): return False
    def clone(self): return Rep(self.e.clone(), self.q)
class CC:
    def __init__(self, chars): self.chars = set(chars)
    def __eq__(self, o): return isinstance(o, CC) and self.chars == o.chars
    def is_empty(self): return False
    def clone(self): return CC(set(self.chars))

CFG = {}

def is_single_codepoint(e):
    return isinstance(e, Lit) and len(e.gs) == 1 and e.gs[0].mn == 1 and e.gs[0].mx == 1 and len(e.gs[0].chars) == 1

def length(e):
    if isinstance(e, Lit): return sum(1 for g in e.gs)  # placeholder
    if isinstance(e, Alt): return max(length(o) for o in e.opts)
    if isinstance(e, Cat): return length(e.a) + length(e.b)
    if isinstance(e, Rep): return length(e.e)
    if isinstance(e, CC): return 1

def to_str(e, top=True):
    if isinstance(e, Lit):
        return "".join(repr(g) for g in e.gs)
    if isinstance(e, CC):
        return fmt_cc(e.chars)
    if isinstance(e, Alt):
        s = "|".join(to_str(o, False) for o in e.opts)
        return "(?:" + s + ")"
    if isinstance(e, Cat):
        return to_str(e.a, False) + to_str(e.b, False)
    if isinstance(e, Rep):
        inner = e.e
        s = to_str(inner, False)
        needs = False
        if isinstance(inner, Lit):
            if len(inner.gs) > 1: needs = True
            elif len(inner.gs) == 1 and (inner.gs[0].mn != 1 or inner.gs[0].mx != 1): needs = True
        elif isinstance(inner, Cat): needs = True
        elif isinstance(inner, Alt): needs = False  # already wrapped
        if needs: s = "(?:" + s + ")"
        return s + e.q

def fmt_cc(chars):
    cs = sorted(chars)
    out = "["
    i = 0
    while i < len(cs):
        j = i
        while j + 1 < len(cs) and ord(cs[j+1]) == ord(cs[j]) + 1: j += 1
        if j - i >= 2: out += cs[i] + "-" + cs[j]
        else: out += "".join(cs[i:j+1])
        i = j + 1
    return out + "]"

