    # returns the Lit at the left edge, or None
    if isinstance(e, Lit): return e
    if isinstance(e, Cat): return first_lit(e.a)
    return None
def last_lit(e):
    if isinstance(e, Lit): return e
    if isinstance(e, Cat): return last_lit(e.b)
    return None

def remove_common_prefix(a, b):
    la, lb = first_lit(a), first_lit(b)
    if la is None or lb is None: return None
    n = 0
    while n < len(la.gs) and n < len(lb.gs) and la.gs[n] == lb.gs[n]: n += 1
    if n == 0: return None
    pre = [g.clone() for g in la.gs[:n]]
    del la.gs[:n]; del lb.gs[:n]
    return Lit(pre)

def remove_common_suffix(a, b):
    la, lb = last_lit(a), last_lit(b)
