    if a.is_empty() or b.is_empty():
        res = Rep(b if a.is_empty() else a, "?")
    elif is_single_codepoint(a) and is_single_codepoint(b):
        res = CC([a.gs[0].chars, b.gs[0].chars])
    elif isinstance(a, CC) and is_single_codepoint(b):
        res = CC(a.chars | {b.gs[0].chars})
    elif is_single_codepoint(a) and isinstance(b, CC):
