        A = W.pop(0) if CFG.get('w_fifo', False) else W.pop()
        for c in alphabet:
            X = {s for s in range(n) if any(lab == c and t in A for (lab, t) in dfa.edges[s])}
            if not X: continue
            newP = []
            for Y in P:
                I = X & Y; D = Y - X
                if I and D:
                    if CFG.get('split_order', 'D_I') == 'D_I':
                        newP.append(D); newP.append(I)
                    elif CFG['split_order'] == 'I_D':
                        newP.append(I); newP.append(D)
                    elif CFG['split_order'] == 'D_inplace_I_append':
                        newP.append(D); newP.append(('APPEND', I))
                    elif CFG['split_order'] == 'I_inplace_D_append':
                        newP.append(I); newP.append(('APPEND', D))
                    if Y in W:
                        W.remove(Y); W.append(I); W.append(D)
                    else:
                        if len(I) <= len(D): W.append(I)
                        else: W.append(D)
                else:
                    newP.append(Y)
            P2 = [p for p in newP if not isinstance(p, tuple)] + [p[1] for p in newP if isinstance(p, tuple)]
            P = P2
    return P

