    m = len(final)
    A = [[None]*m for _ in range(m)]
    B = [None]*m
    for i in range(m):
        if final[i]: B[i] = Lit([])
        es = reversed(edges[i]) if CFG.get('new_edge_rev', False) else edges[i]
        for (lab, j) in es:
            A[i][j] = union(A[i][j], Lit([lab.clone()]))
    for n_ in range(m-1, 0, -1):
        if A[n_][n_] is not None:
            raise Exception("loop")
        for i in range(n_):
            if A[i][n_] is not None:
                B[i] = union(B[i], concat(A[i][n_], B[n_]))
                for j in range(n_):
                    A[i][j] = union(A[i][j], concat(A[i][n_], A[n_][j]))
    return B[0]

