            queue = [start_class]
            while queue:
                c = queue.pop(0)
                # representative: any state in class; gather edges from all states? use min state
                outs = []
                for s in sorted(P[c]):
                    for (lab, t) in (reversed(dfa.edges[s]) if rev else dfa.edges[s]):
                        outs.append(cls_of[t])
                for tc in outs:
                    if tc not in seen: seen.append(tc); queue.append(tc)
        else:
            stack = [start_class]
            seen = []
            while stack:
                c = stack.pop()
                if c in seen: continue
                seen.append(c)
                outs = []
                for s in sorted(P[c]):
                    for (lab, t) in (reversed(dfa.edges[s]) if rev else dfa.edges[s]):
                        outs.append(cls_of[t])
                for tc in reversed(outs):
                    if tc not in seen: stack.append(tc)
        classes = [P[i] for i in seen]
    cls_of = {}
    for i, p in enumerate(classes):
        for s in p: cls_of[s] = i
    m = len(classes)
    final = [any(dfa.final[s] for s in p) for p in classes]
    # edges: collect in old order
    edges = [[] for _ in range(m)]
    for s in range(len(dfa.final)):
        for (lab, t) in (reversed(dfa.edges[s]) if CFG.get('old_edge_rev', False) else dfa.edges[s]):
            e = (lab, cls_of[t])
            if e not in edges[cls_of[s]]:
                edges[cls_of[s]].append(e)
    return final, edges

def to_regex(final, edges):
    m = len(final)
    A = [[None]*m for _ in range(m)]
    B = [None]*m
    for i in range(m):
        if final[i]: B[i] = Lit([])
        es = reversed(edges[i]) if CFG.get('new_edge_rev', False) else edges[i]
        for (lab, j) in es:
            A[i][j] = union(A[i][j], Lit([lab.clone()]))
    for n_ in range(m-1, 0, -1):
        if A[n_][n_] is not None:
            raise Exception("loop")
        for i in range(n_):
            if A[i][n_] is not None:
                B[i] = union(B[i], concat(A[i][n_], B[n_]))
                for j in range(n_):
                    A[i][j] = union(A[i][j], concat(A[i][n_], A[n_][j]))
    return B[0]

def grex(words):
    words = sorted(set(w for w in words if w != ""))
    dfa = DFA()
    for w in words:
        dfa.insert([G(c) for c in w])
    final, edges = minimize(dfa)
    e = to_regex(final, edges)
    if e is None: return "^$"
    s = to_str(e)
    return "^" + s + "$"

if __name__ == "__main__":
    print(grex(sys.argv[1:]))
