import subprocess, random, sys, json, proto
BEST = {'use_min2': True, 'nf_first': True, 'w_final_only': False, 'w_fifo': True, 'alpha_sorted': True, 'split_order': 'D_I',
        'sort': 'len_alpha', 'recreate': 'old_states', 'old_edge_rev': True, 'trav': 'dfs', 'trav_edge_rev': False, 'mat_edge_rev': True,
        'opt_unwrap': True, 'deep_descent': False}
def run_bin(words, extra=[]):
    r = subprocess.run(["/workspace/executable"] + extra + ["--"] + words, capture_output=True, text=True)
    return r.stdout.strip()
def main():
    seed, n, alphabet, maxlen, maxwords = int(sys.argv[1]), int(sys.argv[2]), sys.argv[3], int(sys.argv[4]), int(sys.argv[5])
    extra = sys.argv[6:]
    random.seed(seed)
    proto.CFG.clear(); proto.CFG.update(BEST)
