        exp = run_bin(ws, extra)
        try: got = proto.grex(ws)
        except Exception as e: got = "EXC " + repr(e)
        if exp != got:
            fails += 1
            if fails <= 15: print(ws, "\n   exp:", exp, "\n   got:", got)
