    __slots__ = ('chars', 'reps', 'mn', 'mx')
    def __init__(self, chars, mn=1, mx=1, reps=None):
        self.chars = chars  # str (unit value)
        self.reps = reps    # list of G for repetition units (None for plain)
        self.mn = mn; self.mx = mx
    def __eq__(self, o):
        return isinstance(o, G) and self.chars == o.chars and self.mn == o.mn and self.mx == o.mx and self.reps == o.reps
    def clone(self): return G(self.chars, self.mn, self.mx, [r.clone() for r in self.reps] if self.reps is not None else None)
    def is_plain(self): return self.mn == 1 and self.mx == 1 and self.reps is None
    def __repr__(self):
        if self.reps is not None:
            s = "".join(repr(r) for r in self.reps)
            inner_multi = len(self.reps) > 1 or (len(self.reps) == 1 and not self.reps[0].is_plain())
        else:
            s = self.chars; inner_multi = len(self.chars) > 1
        if self.mn == 1 and self.mx == 1: return s
        if inner_multi: s = "(?:" + s + ")"
        if self.mn == self.mx: return s + "{%d}" % self.mn
        return s + "{%d,%d}" % (self.mn, self.mx)

class Lit:
    def __init__(self, gs): self.gs = gs
    def __eq__(self, o): return isinstance(o, Lit) and self.gs == o.gs
    def clone(self): return Lit([g.clone() for g in self.gs])
class Alt:
    def __init__(self, opts): self.opts = opts
    def __eq__(self, o): return isinstance(o, Alt) and self.opts == o.opts
    def clone(self): return Alt([o.clone() for o in self.opts])
class Cat:
    def __init__(self, a, b): self.a = a; self.b = b
    def __eq__(self, o): return isinstance(o, Cat) and self.a == o.a and self.b == o.b
    def clone(self): return Cat(self.a.clone(), self.b.clone())
class Rep:
    def __init__(self, e): self.e = e
    def __eq__(self, o): return isinstance(o, Rep) and self.e == o.e
    def clone(self): return Rep(self.e.clone())
class CC:
    def __init__(self, chars): self.chars = set(chars)
    def __eq__(self, o): return isinstance(o, CC) and self.chars == o.chars
    def clone(self): return CC(set(self.chars))

def is_empty(e): return isinstance(e, Lit) and len(e.gs) == 0
def is_single(e): return isinstance(e, Lit) and len(e.gs) == 1 and e.gs[0].is_plain() and len(e.gs[0].chars) == 1

def length(e):
    if isinstance(e, Lit): return len(e.gs)
    if isinstance(e, Alt): return max(length(o) for o in e.opts)
    if isinstance(e, Cat): return length(e.a) + length(e.b)
    if isinstance(e, Rep): return length(e.e)
    if isinstance(e, CC): return 1

def to_str(e):
    if isinstance(e, Lit): return "".join(repr(g) for g in e.gs)
    if isinstance(e, CC): return fmt_cc(e.chars)
    if isinstance(e, Alt): return "(?:" + "|".join(to_str(o) for o in e.opts) + ")"
    if isinstance(e, Cat): return to_str(e.a) + to_str(e.b)
    if isinstance(e, Rep):
        inner = e.e; s = to_str(inner)
        needs = False
        if isinstance(inner, Lit):
            if len(inner.gs) > 1: needs = True
            elif len(inner.gs) == 1 and (not inner.gs[0].is_plain() or len(inner.gs[0].chars) > 1): needs = True
        elif isinstance(inner, Cat): needs = True
        if needs: s = "(?:" + s + ")"
        return s + "?"

def fmt_cc(chars):
    cs = sorted(chars); out = "["; i = 0
    while i < len(cs):
        j = i
        while j + 1 < len(cs) and ord(cs[j+1]) == ord(cs[j]) + 1: j += 1
        if j - i >= 2: out += cs[i] + "-" + cs[j]
        else: out += "".join(cs[i:j+1])
        i = j + 1
    return out + "]"

# ---- algebra ----
def flatten(opts, e):
    if isinstance(e, Alt):
        for o in e.opts: flatten(opts, o)
    else: opts.append(e)

def new_alt(a, b):
    optional = False
    if isinstance(a, Rep): a = a.e; optional = True
    if isinstance(b, Rep): b = b.e; optional = True
    opts = []; flatten(opts, a); flatten(opts, b)
    # dedupe
    ded = []
    for o in opts:
        if not any(o == d for d in ded): ded.append(o)
    opts = ded
    opts.sort(key=lambda o: -length(o))
    res = Alt(opts) if len(opts) > 1 else opts[0]
    return Rep(res) if optional else res

def first_lit(e):
    if isinstance(e, Lit): return e
    if isinstance(e, Cat) and isinstance(e.a, Lit): return e.a
    return None
def last_lit(e):
    if isinstance(e, Lit): return e
    if isinstance(e, Cat) and isinstance(e.b, Lit): return e.b
    return None

def adjacent_extends(big, small):
    # big is a repetition extension of small: same chars, big.mn == small.mx + 1
    return big.chars == small.chars and big.reps == small.reps and big.mn == small.mx + 1

def merged(g1, g2):
    return G(g1.chars, min(g1.mn, g2.mn), max(g1.mx, g2.mx), g1.reps)

def common_prefix_graphemes(l1, l2):
    """Return list of prefix graphemes (possibly merged) per observed rules, or []"""
    n = 0
    while n < len(l1) and n < len(l2) and l1[n].chars == l2[n].chars and l1[n].reps == l2[n].reps: n += 1
    if n == 0: return []
    # exact?
    if all(l1[i] == l2[i] for i in range(n)): return [g.clone() for g in l1[:n]]
    # try direction: l1 extends l2 (requires len(l1) >= len(l2))
    for big, small in ((l1, l2), (l2, l1)):
        if len(big) >= len(small):
            ok = True
            for i in range(n):
                if big[i] == small[i]: continue
                if adjacent_extends(big[i], small[i]): continue
                ok = False; break
            if ok:
                return [merged(big[i], small[i]) if big[i] != small[i] else big[i].clone() for i in range(n)]
    return []

def remove_prefix(e, k):
    # remove k graphemes from the first literal of e
    if isinstance(e, Lit):
        return Lit([g.clone() for g in e.gs[k:]])
    if isinstance(e, Cat):
        rest = Lit([g.clone() for g in e.a.gs[k:]])
        if len(rest.gs) == 0: return e.b.clone()   # observed: prefix removal drops the empty literal
        return Cat(rest, e.b.clone())

def remove_suffix(e, k):
    if isinstance(e, Lit):
        return Lit([g.clone() for g in e.gs[:len(e.gs)-k]])
    if isinstance(e, Cat):
        rest = Lit([g.clone() for g in e.b.gs[:len(e.b.gs)-k]])
        return Cat(e.a.clone(), rest)   # kept even if empty (observed)

def union(a, b):
    if a is None: return b
    if b is None: return a
    if a == b: return a
    a = a.clone(); b = b.clone()
    # repetition merge with char class
    r = cc_rep_merge(a, b)
    if r is not None: return r
    r = cc_rep_merge(b, a)
    if r is not None: return r
    pre = None; suf = None
    la, lb = first_lit(a), first_lit(b)
    if la is not None and lb is not None:
        pg = common_prefix_graphemes(la.gs, lb.gs)
        if pg:
            a = remove_prefix(a, len(pg)); b = remove_prefix(b, len(pg)); pre = Lit(pg)
    la, lb = last_lit(a), last_lit(b)
    if la is not None and lb is not None:
        n = 0
        while n < len(la.gs) and n < len(lb.gs) and la.gs[-1-n] == lb.gs[-1-n]: n += 1
        if n:
            suf = Lit([g.clone() for g in la.gs[len(la.gs)-n:]])
            a = remove_suffix(a, n); b = remove_suffix(b, n)
    if is_empty(a) or is_empty(b):
        res = Rep(b if is_empty(a) else a)
    elif is_single(a) and is_single(b):
        res = CC([a.gs[0].chars, b.gs[0].chars])
    elif isinstance(a, CC) and is_single(b):
        res = CC(a.chars | {b.gs[0].chars})
    elif is_single(a) and isinstance(b, CC):
        res = CC(b.chars | {a.gs[0].chars})
    elif isinstance(a, CC) and isinstance(b, CC):
        res = CC(a.chars | b.chars)
    else:
        res = new_alt(a, b)
    if pre is not None: res = concat(pre, res)
    if suf is not None: res = concat(res, suf)
    return res

def cc_rep_merge(x, l):
    """x is CC or Alt; l is a Lit whose first grapheme is a repetition of a single char in x."""
    if not isinstance(l, Lit) or len(l.gs) == 0: return None
    g = l.gs[0]
    if g.reps is not None or len(g.chars) != 1 or g.mn != 2: return None
    c = g.chars
    if isinstance(x, CC):
        if c not in x.chars: return None
        m = G(c, 1, g.mx)
        if len(l.gs) == 1:
            acc = None
            for ch in sorted(x.chars):
                item = Lit([m.clone()]) if ch == c else Lit([G(ch)])
                acc = item if acc is None else fold_union(acc, item)
            return acc
        rest_chars = x.chars - {c}
        rest = CC(rest_chars) if len(rest_chars) > 1 else Lit([G(next(iter(rest_chars)))])
        l2 = Lit([m.clone()] + [gg.clone() for gg in l.gs[1:]])
        return union(Lit([m.clone()]), union(rest, l2))
    if isinstance(x, Alt):
        for i, o in enumerate(x.opts):
            if isinstance(o, Lit) and len(o.gs) == 1 and o.gs[0].reps is None and o.gs[0].chars == c and adjacent_extends(g, o.gs[0]):
                m = merged(g, o.gs[0])
                if len(l.gs) == 1:
                    opts = [oo.clone() for oo in x.opts]; opts[i] = Lit([m])
                    return new_alt_list(opts)
                opts = [oo.clone() for oo in x.opts]; opts[i] = Lit([m.clone()])
                l2 = Lit([m.clone()] + [gg.clone() for gg in l.gs[1:]])
                return new_alt_list(opts + [l2])
            if isinstance(o, CC) and c in o.chars:
                sub = cc_rep_merge(o, l)
                opts = [oo.clone() for oo in x.opts]; opts[i] = sub
                return new_alt_list(opts)
    return None

def new_alt_list(items):
    acc = None
    for it in items: acc = it if acc is None else new_alt(acc, it)
    return acc

def fold_union(acc, item):
    # sequential refold: singles -> class, else alt append (no prefix/suffix)
    if is_single(acc) and is_single(item): return CC([acc.gs[0].chars, item.gs[0].chars])
    if isinstance(acc, CC) and is_single(item): return CC(acc.chars | {item.gs[0].chars})
    return new_alt(acc, item)

def concat(a, b):
    if a is None or b is None: return None
    if is_empty(a): return b
    if is_empty(b): return a
    if isinstance(a, Lit) and isinstance(b, Lit): return Lit([g.clone() for g in a.gs] + [g.clone() for g in b.gs])
    if isinstance(a, Lit) and isinstance(b, Cat) and isinstance(b.a, Lit):
        return Cat(Lit([g.clone() for g in a.gs] + [g.clone() for g in b.a.gs]), b.b.clone())
    if isinstance(b, Lit) and isinstance(a, Cat) and isinstance(a.b, Lit):
        return Cat(a.a.clone(), Lit([g.clone() for g in a.b.gs] + [g.clone() for g in b.gs]))
    return Cat(a, b)

# ---- repetition detection ----
def convert_repetitions(gs, min_reps, min_len):
    n = len(gs)
    cands = []
    for L in range(1, n // 2 + 1):
        positions = {}
        for i in range(0, n - L + 1):
            key = tuple(g.chars for g in gs[i:i+L])
            positions.setdefault(key, []).append(i)
        for key, pos in positions.items():
            # runs of consecutive positions with step L
            i = 0
            while i < len(pos):
                j = i
                while j + 1 < len(pos) and pos[j+1] == pos[j] + L: j += 1
                count = j - i + 1
                if count >= 2 and count - 1 >= min_reps and L >= min_len:
                    cands.append((pos[i], pos[i] + count * L, L, count))
                i = j + 1
    cands.sort(key=lambda c: (-c[1], c[0]))
    applied = []
    for (s, e, L, cnt) in cands:
        if any(not (e <= s2 or s >= e2) for (s2, e2, _, _) in applied): continue
        applied.append((s, e, L, cnt))
    applied.sort()
    out = []; i = 0
    for (s, e, L, cnt) in applied:
        out.extend(g.clone() for g in gs[i:s])
        unit = convert_repetitions([g.clone() for g in gs[s:s+L]], min_reps, min_len)
        out.append(G("".join(g.chars for g in unit), cnt, cnt, unit))
        i = e
    out.extend(g.clone() for g in gs[i:])
    return out

# ---- DFA ----
class DFA:
    def __init__(self):
        self.final = [False]; self.edges = [[]]
    def add_state(self):
        self.final.append(False); self.edges.append([]); return len(self.final) - 1
    def insert(self, graphemes):
        s = 0
        for g in graphemes:
            nxt = None
            for (lab, t) in self.edges[s]:
                if lab == g: nxt = t; break
            if nxt is None:
                nxt = self.add_state(); self.edges[s].append((g, nxt))
            s = nxt
        self.final[s] = True

def hopcroft(dfa):
    n = len(dfa.final)
    F = frozenset(s for s in range(n) if dfa.final[s]); NF = frozenset(range(n)) - F
    P = [p for p in (NF, F) if p]
    W = list(P)
    alphabet = []
    for s in range(n):
        for (lab, t) in dfa.edges[s]:
            if lab not in alphabet: alphabet.append(lab)
    while W:
        A = W.pop(0)
        for c in alphabet:
            X = frozenset(s for s in range(n) if any(lab == c and t in A for (lab, t) in dfa.edges[s]))
            if not X: continue
            newP = []
            for Y in P:
                I = X & Y; D = Y - X
                if I and D:
                    newP += [D, I]
                    if Y in W: W.remove(Y); W += [I, D]
                    else: W.append(I if len(I) <= len(D) else D)
                else: newP.append(Y)
            P = newP
    return P

def minimize(dfa):
    P = hopcroft(dfa)
    cls_of = {}
    for i, p in enumerate(P):
        for s in p: cls_of[s] = i
    new_id = {}; new_final = []; new_edges = []
    def node_for(c):
        if c not in new_id:
            new_id[c] = len(new_final); new_final.append(any(dfa.final[s] for s in P[c])); new_edges.append([])
        return new_id[c]
    for s in range(len(dfa.final)): node_for(cls_of[s])
    for s in range(len(dfa.final)):
        for (lab, t) in reversed(dfa.edges[s]):
            u, v = new_id[cls_of[s]], new_id[cls_of[t]]
            if (lab, v) not in new_edges[u]: new_edges[u].append((lab, v))
    start = new_id[cls_of[0]]
    order = []
    def dfs(u):
        if u in order: return
        order.append(u)
        for (lab, v) in new_edges[u]: dfs(v)
    dfs(start)
    pos = {u: i for i, u in enumerate(order)}
    final = [new_final[u] for u in order]
    edges = [[(lab, pos[v]) for (lab, v) in reversed(new_edges[u])] for u in order]
    return final, edges

def to_regex(final, edges):
    m = len(final)
    A = [[None]*m for _ in range(m)]; B = [None]*m
    for i in range(m):
        if final[i]: B[i] = Lit([])
        for (lab, j) in edges[i]:
            A[i][j] = union(A[i][j], Lit([lab.clone()]))
    for n_ in range(m-1, 0, -1):
        for i in range(n_):
            if A[i][n_] is not None:
                B[i] = union(B[i], concat(A[i][n_], B[n_]))
                for j in range(n_):
                    A[i][j] = union(A[i][j], concat(A[i][n_], A[n_][j]))
    return B[0]

def grex(words, reps=False, min_reps=1, min_len=1):
    ws = set(w for w in words if w != "")
    words = sorted(ws, key=lambda w: (len(w), w))
    dfa = DFA()
    for w in words:
        gs = [G(c) for c in w]
        if reps: gs = convert_repetitions(gs, min_reps, min_len)
        dfa.insert(gs)
    final, edges = minimize(dfa)
    e = to_regex(final, edges)
    return "^" + (to_str(e) if e is not None else "") + "$"

if __name__ == "__main__":
    args = sys.argv[1:]
    reps = False
    if args and args[0] == "-r": reps = True; args = args[1:]
    print(grex(args, reps))
