//! Graphemes: the atomic units of the regular expression literals.

use std::fmt::Write;

/// A single unit within a literal. A unit is either a single code point (which may be
/// escaped on output), a special marker such as `\d` or an already escaped sequence
/// such as `\u{1f4a9}`.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Unit {
    Char(char),
    /// a shorthand character class like `\d`, `\s`, `\w`, `\D`, `\S`, `\W`
    Class(&'static str),
    /// a unicode escape sequence like `\u{ff}`
    Escaped(String),
}

impl Unit {
    pub fn key(&self) -> String {
        match self {
            Unit::Char(c) => c.to_string(),
            Unit::Class(s) => s.to_string(),
            Unit::Escaped(s) => s.clone(),
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Grapheme {
    pub units: Vec<Unit>,
    /// the repeated sub-sequence (empty for plain graphemes)
    pub reps: Vec<Grapheme>,
    pub min: u32,
    pub max: u32,
}

impl Grapheme {
    pub fn plain(unit: Unit) -> Self {
        Grapheme {
            units: vec![unit],
            reps: vec![],
            min: 1,
            max: 1,
        }
    }

    pub fn repetition(reps: Vec<Grapheme>, count: u32) -> Self {
        if reps.len() == 1 && reps[0].is_plain() {
            let mut g = reps[0].clone();
            g.min = count;
            g.max = count;
            return g;
        }
        let units = reps.iter().flat_map(|g| g.units.iter().cloned()).collect();
        Grapheme {
            units,
            reps,
            min: count,
            max: count,
        }
    }

    pub fn is_plain(&self) -> bool {
        self.min == 1 && self.max == 1 && self.reps.is_empty()
    }

    pub fn has_quantifier(&self) -> bool {
        !(self.min == 1 && self.max == 1)
    }

    /// The single code point of this grapheme, if it is a plain single character.
    pub fn codepoint(&self) -> Option<char> {
        if self.units.len() == 1 {
            if let Unit::Char(c) = self.units[0] {
                return Some(c);
            }
        }
        None
    }

    pub fn is_single_codepoint(&self) -> bool {
        self.is_plain() && self.codepoint().is_some()
    }

    /// Key used to compare graphemes ignoring their repetition range.
    pub fn family_key(&self) -> (Vec<String>, Vec<Grapheme>) {
        (self.units.iter().map(|u| u.key()).collect(), self.reps.clone())
    }

    pub fn same_family(&self, other: &Grapheme) -> bool {
        self.units == other.units && self.reps == other.reps
    }

    /// Number of displayed units; a backslash counts as two.
    pub fn unit_count(&self) -> usize {
        if self.codepoint() == Some('\\') {
            2
        } else {
            self.units.len()
        }
    }

    /// Whether this grapheme must be wrapped in a group when a quantifier is applied.
    pub fn needs_group(&self) -> bool {
        if self.reps.is_empty() {
            self.unit_count() > 1
        } else if self.reps.len() > 1 {
            true
        } else {
            self.reps[0].needs_group() || self.reps[0].has_quantifier()
        }
    }

    pub fn quantifier(&self) -> String {
        if self.min == self.max {
            format!("{{{}}}", self.min)
        } else {
            format!("{{{},{}}}", self.min, self.max)
        }
    }
}

pub fn escape_char(c: char, verbose: bool, out: &mut String) {
    match c {
        '\\' => out.push_str("\\\\"),
        '(' | ')' | '*' | '+' | '-' | '.' | '?' | '[' | ']' | '^' | '{' | '|' | '}' | '$' => {
            out.push('\\');
            out.push(c);
        }
        ' ' | '#' if verbose => {
            out.push('\\');
            out.push(c);
        }
        _ => out.push(c),
    }
}

pub fn escape_class_char(c: char, verbose: bool, out: &mut String) {
    match c {
        '[' | ']' | '\\' | '^' | '-' | '$' => {
            out.push('\\');
            out.push(c);
        }
        ' ' | '#' if verbose => {
