    }
}

pub fn unicode_escape(c: char, with_surrogates: bool) -> Vec<Unit> {
    let cp = c as u32;
    if with_surrogates && cp > 0xFFFF {
        let v = cp - 0x10000;
        let high = 0xD800 + (v >> 10);
        let low = 0xDC00 + (v & 0x3FF);
        vec![
            Unit::Escaped(format!("\\u{{{:x}}}", high)),
            Unit::Escaped(format!("\\u{{{:x}}}", low)),
        ]
    } else {
        vec![Unit::Escaped(format!("\\u{{{:x}}}", cp))]
    }
}

/// Detect repeated non-overlapping substrings and convert them into repetition graphemes.
pub fn convert_repetitions(gs: &[Grapheme], min_reps: u32, min_len: u32) -> Vec<Grapheme> {
    let n = gs.len();
    // candidates: (start, end, length, count)
    let mut cands: Vec<(usize, usize, usize, usize)> = Vec::new();
    let keys: Vec<(Vec<String>, Vec<Grapheme>)> = gs.iter().map(|g| g.family_key()).collect();
    for len in 1..=(n / 2) {
        // positions grouped by substring, in order of first appearance
        let mut groups: Vec<(Vec<&(Vec<String>, Vec<Grapheme>)>, Vec<usize>)> = Vec::new();
        for i in 0..=(n - len) {
            let sub: Vec<&(Vec<String>, Vec<Grapheme>)> = keys[i..i + len].iter().collect();
            if let Some(entry) = groups.iter_mut().find(|(k, _)| *k == sub) {
                entry.1.push(i);
            } else {
                groups.push((sub, vec![i]));
            }
        }
        for (_, pos) in groups {
            let mut i = 0;
            while i < pos.len() {
                let mut j = i;
                while j + 1 < pos.len() && pos[j + 1] == pos[j] + len {
                    j += 1;
                }
                let count = j - i + 1;
                if count >= 2 && (count - 1) as u32 >= min_reps && len as u32 >= min_len {
                    cands.push((pos[i], pos[i] + count * len, len, count));
                }
                i = j + 1;
            }
        }
    }
    // sort by end descending, then start ascending
    cands.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    let mut applied: Vec<(usize, usize, usize, usize)> = Vec::new();
    for c in cands {
        if applied
            .iter()
            .any(|a| !(c.1 <= a.0 || c.0 >= a.1))
        {
            continue;
        }
        applied.push(c);
    }
    applied.sort();
    let mut out = Vec::new();
    let mut i = 0;
    for (s, e, len, cnt) in applied {
        out.extend(gs[i..s].iter().cloned());
        let unit = convert_repetitions(&gs[s..s + len], min_reps, min_len);
        out.push(Grapheme::repetition(unit, cnt as u32));
        i = e;
    }
    out.extend(gs[i..].iter().cloned());
    out
}

