//! The regular expression AST and the algebra used to build it from a DFA.

use crate::grapheme::Grapheme;
use std::collections::BTreeSet;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Expr {
    Lit(Vec<Grapheme>),
    Alt(Vec<Expr>),
    Cat(Box<Expr>, Box<Expr>),
    Rep(Box<Expr>),
    Class(BTreeSet<char>),
}

/// The context in which a union is computed. It influences the direction in which
/// adjacent repetition ranges may be merged.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Ctx {
    /// building the transition matrix from edge labels
    Labels,
    /// updating matrix entries while eliminating a state
    Matrix,
    /// updating the result vector while eliminating a state
    Vector,
}

pub fn lit(g: Grapheme) -> Expr {
    Expr::Lit(vec![g])
}

pub fn empty() -> Expr {
    Expr::Lit(vec![])
}

impl Expr {
    pub fn is_empty(&self) -> bool {
        matches!(self, Expr::Lit(gs) if gs.is_empty())
    }

    pub fn is_single_codepoint(&self) -> bool {
        match self {
            Expr::Lit(gs) => gs.len() == 1 && gs[0].is_single_codepoint(),
            _ => false,
        }
    }

    pub fn single_codepoint(&self) -> Option<char> {
        match self {
            Expr::Lit(gs) if gs.len() == 1 => {
                if gs[0].is_plain() {
                    gs[0].codepoint()
                } else {
                    None
                }
            }
            _ => None,
        }
    }

    pub fn len(&self) -> usize {
        match self {
            Expr::Lit(gs) => gs.len(),
            Expr::Alt(opts) => opts.iter().map(|o| o.len()).max().unwrap_or(0),
            Expr::Cat(a, b) => a.len() + b.len(),
            Expr::Rep(e) => e.len(),
            Expr::Class(_) => 1,
        }
    }
}

fn flatten(out: &mut Vec<Expr>, e: Expr) {
    match e {
        Expr::Alt(opts) => {
            for o in opts {
                flatten(out, o);
            }
        }
        other => out.push(other),
    }
}

pub fn new_alt(a: Expr, b: Expr) -> Expr {
    let mut optional = false;
    let a = match a {
        Expr::Rep(inner) => {
            optional = true;
            *inner
        }
        other => other,
    };
    let b = match b {
        Expr::Rep(inner) => {
            optional = true;
            *inner
        }
        other => other,
    };
    let mut opts = Vec::new();
    flatten(&mut opts, a);
    flatten(&mut opts, b);
    let mut ded: Vec<Expr> = Vec::new();
    for o in opts {
        if !ded.contains(&o) {
            ded.push(o);
        }
    }
    ded.sort_by_key(|o| std::cmp::Reverse(o.len()));
    let res = if ded.len() == 1 {
        ded.pop().unwrap()
    } else {
        Expr::Alt(ded)
    };
    if optional {
        Expr::Rep(Box::new(res))
    } else {
        res
    }
}

fn new_alt_list(items: Vec<Expr>) -> Expr {
    let mut acc: Option<Expr> = None;
    for it in items {
        acc = Some(match acc {
            None => it,
            Some(a) => new_alt(a, it),
        });
    }
    acc.unwrap()
}

fn first_lit(e: &Expr) -> Option<&Vec<Grapheme>> {
    match e {
        Expr::Lit(gs) => Some(gs),
        Expr::Cat(a, _) => match a.as_ref() {
            Expr::Lit(gs) => Some(gs),
            _ => None,
        },
        _ => None,
    }
}

fn last_lit(e: &Expr) -> Option<&Vec<Grapheme>> {
    match e {
        Expr::Lit(gs) => Some(gs),
        Expr::Cat(_, b) => match b.as_ref() {
            Expr::Lit(gs) => Some(gs),
            _ => None,
        },
        _ => None,
    }
}

/// `big` is a repetition extension of `small`: same unit, `big.min == small.max + 1`.
fn adjacent_extends(big: &Grapheme, small: &Grapheme) -> bool {
    big.same_family(small) && big.min == small.max + 1
}

fn merged(g1: &Grapheme, g2: &Grapheme) -> Grapheme {
    let mut m = g1.clone();
    m.min = g1.min.min(g2.min);
    m.max = g1.max.max(g2.max);
    m
}

fn common_prefix(l1: &[Grapheme], l2: &[Grapheme], ctx: Ctx) -> Vec<Grapheme> {
    let mut out = Vec::new();
    let mut n = 0;
    while n < l1.len() && n < l2.len() {
        let (g1, g2) = (&l1[n], &l2[n]);
        if g1 == g2 {
            out.push(g1.clone());
        } else if adjacent_extends(g2, g1) && l1.len() <= l2.len() + 1 {
            out.push(merged(g2, g1));
        } else if ctx == Ctx::Matrix && adjacent_extends(g1, g2) && l2.len() <= l1.len() + 1 {
            out.push(merged(g1, g2));
        } else {
            break;
        }
        n += 1;
    }
    out
}

fn remove_prefix(e: Expr, k: usize, merged_prefix: bool) -> Expr {
    match e {
        Expr::Lit(gs) => Expr::Lit(gs[k..].to_vec()),
        Expr::Cat(a, b) => {
            if let Expr::Lit(gs) = *a {
                let rest = gs[k..].to_vec();
                if rest.is_empty() && merged_prefix {
                    return *b;
                }
                Expr::Cat(Box::new(Expr::Lit(rest)), b)
            } else {
                Expr::Cat(a, b)
            }
        }
        other => other,
    }
}

fn remove_suffix(e: Expr, k: usize) -> Expr {
    match e {
        Expr::Lit(gs) => {
            let n = gs.len() - k;
            Expr::Lit(gs[..n].to_vec())
        }
        Expr::Cat(a, b) => {
            if let Expr::Lit(gs) = *b {
                let n = gs.len() - k;
                Expr::Cat(a, Box::new(Expr::Lit(gs[..n].to_vec())))
            } else {
                Expr::Cat(a, b)
            }
        }
        other => other,
    }
}

pub fn union(a: Option<Expr>, b: Option<Expr>, ctx: Ctx) -> Option<Expr> {
    match (a, b) {
        (None, b) => b,
        (a, None) => a,
        (Some(a), Some(b)) => Some(union2(a, b, ctx)),
    }
}

fn union2(a: Expr, b: Expr, ctx: Ctx) -> Expr {
    if a == b {
        return a;
    }
    if let Some(r) = rep_merge(&a, &b, ctx) {
        return r;
    }
    if let Some(r) = rep_merge(&b, &a, ctx) {
        return r;
    }
    let mut a = a;
    let mut b = b;
    let mut prefix: Option<Vec<Grapheme>> = None;
    let mut suffix: Option<Vec<Grapheme>> = None;
    if let (Some(la), Some(lb)) = (first_lit(&a), first_lit(&b)) {
        let pg = common_prefix(la, lb, ctx);
        if !pg.is_empty() {
            let merged_prefix = (0..pg.len()).any(|i| la[i] != lb[i]);
            let k = pg.len();
            a = remove_prefix(a, k, merged_prefix);
            b = remove_prefix(b, k, merged_prefix);
            prefix = Some(pg);
        }
    }
    if let (Some(la), Some(lb)) = (last_lit(&a), last_lit(&b)) {
        let mut n = 0;
        while n < la.len() && n < lb.len() && la[la.len() - 1 - n] == lb[lb.len() - 1 - n] {
            n += 1;
        }
        if n > 0 {
            let suf = la[la.len() - n..].to_vec();
            a = remove_suffix(a, n);
            b = remove_suffix(b, n);
            suffix = Some(suf);
        }
    }
    let mut res = if a == b {
        a
    } else if a.is_empty() || b.is_empty() {
        Expr::Rep(Box::new(if a.is_empty() { b } else { a }))
    } else if let (Some(ca), Some(cb)) = (a.single_codepoint(), b.single_codepoint()) {
        let mut set = BTreeSet::new();
        set.insert(ca);
        set.insert(cb);
        Expr::Class(set)
    } else if let (Expr::Class(set), Some(c)) = (&a, b.single_codepoint()) {
        let mut set = set.clone();
        set.insert(c);
        Expr::Class(set)
    } else if let (Some(c), Expr::Class(set)) = (a.single_codepoint(), &b) {
        let mut set = set.clone();
        set.insert(c);
        Expr::Class(set)
    } else if let (Expr::Class(sa), Expr::Class(sb)) = (&a, &b) {
        Expr::Class(sa.union(sb).cloned().collect())
    } else {
        new_alt(a, b)
    };
    if let Some(p) = prefix {
        res = concat(Expr::Lit(p), res);
    }
    if let Some(s) = suffix {
        res = concat(res, Expr::Lit(s));
    }
    res
}

/// Sequential refold of items into classes/alternations without prefix/suffix extraction.
fn fold_union(acc: Expr, item: Expr) -> Expr {
    if let (Some(ca), Some(cb)) = (acc.single_codepoint(), item.single_codepoint()) {
        let mut set = BTreeSet::new();
        set.insert(ca);
        set.insert(cb);
        return Expr::Class(set);
    }
    if let (Expr::Class(set), Some(c)) = (&acc, item.single_codepoint()) {
        let mut set = set.clone();
        set.insert(c);
        return Expr::Class(set);
    }
    new_alt(acc, item)
}

fn class_rest(set: &BTreeSet<char>, c: char) -> Option<Expr> {
    let rest: BTreeSet<char> = set.iter().cloned().filter(|x| *x != c).collect();
    match rest.len() {
        0 => None,
        1 => Some(lit(Grapheme::plain(crate::grapheme::Unit::Char(*rest.iter().next().unwrap())))),
        _ => Some(Expr::Class(rest)),
    }
}

fn block(opts: Vec<Expr>) -> Option<Expr> {
    match opts.len() {
        0 => None,
        1 => Some(opts.into_iter().next().unwrap()),
        _ => Some(Expr::Alt(opts)),
    }
}

/// Matching of an existing single grapheme against the first grapheme of a literal.
fn matches(e: &Grapheme, g: &Grapheme, ctx: Ctx) -> Option<Grapheme> {
    if !e.same_family(g) {
        return None;
    }
    if e == g {
        return Some(e.clone());
    }
    if adjacent_extends(g, e) {
        return Some(merged(g, e));
    }
    if ctx == Ctx::Matrix && adjacent_extends(e, g) {
        return Some(merged(g, e));
    }
    None
}

/// Merge the first grapheme of literal `l` into a matching single-character member of
/// the class or alternation `x`.
fn rep_merge(x: &Expr, l: &Expr, ctx: Ctx) -> Option<Expr> {
    let lgs = match l {
        Expr::Lit(gs) if !gs.is_empty() => gs,
        _ => return None,
    };
    let g = &lgs[0];
    if !g.reps.is_empty() || g.units.len() != 1 {
        return None;
    }
    let c = match g.codepoint() {
        Some(c) => c,
        None => return None,
    };
    let finish = |m: Grapheme, others: Option<Expr>, is_last: bool| -> Expr {
        let mut l2 = vec![m.clone()];
        l2.extend(lgs[1..].iter().cloned());
        let l2 = Expr::Lit(l2);
        if is_last {
            let inner = union2(lit(m), l2, ctx);
            match others {
                Some(o) => union2(o, inner, ctx),
                None => inner,
            }
        } else {
            let inner = match others {
                Some(o) => union2(o, l2, ctx),
                None => l2,
            };
            union2(lit(m), inner, ctx)
        }
    };
    match x {
        Expr::Class(set) => {
            if !set.contains(&c) || g.min != 2 {
                return None;
            }
            let mut m = g.clone();
            m.min = 1;
            if lgs.len() == 1 {
                let mut acc: Option<Expr> = None;
                for ch in set.iter() {
                    let item = if *ch == c {
                        lit(m.clone())
                    } else {
                        lit(Grapheme::plain(crate::grapheme::Unit::Char(*ch)))
                    };
                    acc = Some(match acc {
                        None => item,
                        Some(a) => fold_union(a, item),
                    });
                }
                return acc;
            }
            let is_last = *set.iter().next_back().unwrap() == c;
            Some(finish(m, class_rest(set, c), is_last))
        }
        Expr::Alt(opts) => {
            for (i, o) in opts.iter().enumerate() {
                match o {
                    Expr::Lit(ogs) if ogs.len() == 1 => {
                        if let Some(m) = matches(&ogs[0], g, ctx) {
                            if lgs.len() == 1 {
                                let mut new_opts = opts.clone();
                                new_opts[i] = lit(m);
                                return Some(new_alt_list(new_opts));
                            }
                            let others = block(
                                opts.iter()
                                    .enumerate()
                                    .filter(|(j, _)| *j != i)
                                    .map(|(_, o)| o.clone())
                                    .collect(),
                            );
                            let is_last = i == opts.len() - 1 && m != ogs[0];
                            return Some(finish(m, others, is_last));
                        }
                    }
                    Expr::Class(set) if set.contains(&c) && (g.is_plain() || g.min == 2) => {
                        let mut m = g.clone();
                        m.min = 1;
                        if lgs.len() == 1 {
                            let sub = if g.min == 2 {
                                rep_merge(o, l, ctx).unwrap_or_else(|| o.clone())
                            } else {
                                o.clone()
                            };
                            let mut new_opts = opts.clone();
                            new_opts[i] = sub;
                            return Some(new_alt_list(new_opts));
                        }
                        let rest = class_rest(set, c);
                        let mut others_list: Vec<Expr> = opts
                            .iter()
                            .enumerate()
                            .filter(|(j, _)| *j != i)
                            .map(|(_, o)| o.clone())
                            .collect();
                        if let Some(r) = rest {
                            others_list.insert(i, r);
                        }
                        let is_last =
                            i == opts.len() - 1 && *set.iter().next_back().unwrap() == c && g.min == 2;
                        return Some(finish(m, block(others_list), is_last));
                    }
                    _ => {}
                }
            }
            None
        }
        _ => None,
    }
}

pub fn concat(a: Expr, b: Expr) -> Expr {
    if a.is_empty() {
        return b;
    }
    if b.is_empty() {
        return a;
    }
    match (a, b) {
        (Expr::Lit(mut x), Expr::Lit(y)) => {
            x.extend(y);
            Expr::Lit(x)
        }
        (Expr::Lit(mut x), Expr::Cat(ba, bb)) => {
            if let Expr::Lit(y) = *ba {
                x.extend(y);
                Expr::Cat(Box::new(Expr::Lit(x)), bb)
            } else {
                Expr::Cat(Box::new(Expr::Lit(x)), Box::new(Expr::Cat(ba, bb)))
            }
        }
        (Expr::Cat(aa, ab), Expr::Lit(y)) => {
            if let Expr::Lit(mut x) = *ab {
                x.extend(y);
                Expr::Cat(aa, Box::new(Expr::Lit(x)))
            } else {
                Expr::Cat(Box::new(Expr::Cat(aa, ab)), Box::new(Expr::Lit(y)))
            }
        }
        (a, b) => Expr::Cat(Box::new(a), Box::new(b)),
    }
}

pub fn concat_opt(a: &Option<Expr>, b: &Option<Expr>) -> Option<Expr> {
    match (a, b) {
        (Some(a), Some(b)) => Some(concat(a.clone(), b.clone())),
        _ => None,
    }
}
