//! Deterministic finite automaton built from the test cases, its minimization and the
//! conversion into a regular expression by means of Brzozowski's algebraic method.

use crate::expression::{concat_opt, lit, union, Ctx, Expr};
use crate::grapheme::Grapheme;
use std::collections::BTreeSet;

pub struct Dfa {
    is_final: Vec<bool>,
    edges: Vec<Vec<(Grapheme, usize)>>,
}

impl Dfa {
    pub fn new() -> Self {
        Dfa {
            is_final: vec![false],
            edges: vec![vec![]],
        }
    }

    fn add_state(&mut self) -> usize {
        self.is_final.push(false);
        self.edges.push(vec![]);
        self.is_final.len() - 1
    }

    pub fn insert(&mut self, graphemes: &[Grapheme]) {
        let mut s = 0;
        for g in graphemes {
            let mut next = None;
            // the most recently added edge of the same family decides
            for (label, target) in self.edges[s].iter().rev() {
                if label.same_family(g) {
                    if label == g {
                        next = Some(*target);
                    }
                    break;
                }
            }
            let t = match next {
                Some(t) => t,
                None => {
                    let t = self.add_state();
                    self.edges[s].push((g.clone(), t));
                    t
                }
            };
            s = t;
        }
        self.is_final[s] = true;
    }

    fn partition(&self) -> Vec<BTreeSet<usize>> {
        let n = self.is_final.len();
        let finals: BTreeSet<usize> = (0..n).filter(|s| self.is_final[*s]).collect();
        let non_finals: BTreeSet<usize> = (0..n).filter(|s| !self.is_final[*s]).collect();
        let mut p: Vec<BTreeSet<usize>> = Vec::new();
        if !non_finals.is_empty() {
            p.push(non_finals);
        }
        if !finals.is_empty() {
            p.push(finals);
        }
        let mut w: Vec<BTreeSet<usize>> = p.clone();
        let mut alphabet: Vec<Grapheme> = Vec::new();
        for s in 0..n {
            for (label, _) in &self.edges[s] {
                if !alphabet.contains(label) {
                    alphabet.push(label.clone());
                }
            }
        }
        while !w.is_empty() {
            let a = w.remove(0);
            for c in &alphabet {
                let x: BTreeSet<usize> = (0..n)
                    .filter(|s| {
                        self.edges[*s]
                            .iter()
                            .any(|(label, t)| label == c && a.contains(t))
                    })
                    .collect();
                if x.is_empty() {
                    continue;
                }
                let mut new_p = Vec::new();
                for y in p.iter() {
                    let i: BTreeSet<usize> = x.intersection(y).cloned().collect();
                    let d: BTreeSet<usize> = y.difference(&x).cloned().collect();
                    if !i.is_empty() && !d.is_empty() {
                        new_p.push(d.clone());
                        new_p.push(i.clone());
                        if let Some(pos) = w.iter().position(|z| z == y) {
                            w.remove(pos);
                            w.push(i);
                            w.push(d);
                        } else if i.len() <= d.len() {
                            w.push(i);
                        } else {
                            w.push(d);
                        }
                    } else {
                        new_p.push(y.clone());
                    }
                }
                p = new_p;
            }
        }
        p
    }

    /// Minimizes the automaton and returns, in traversal order, the finality of each state
    /// and its outgoing edges.
    pub fn minimize(&self) -> (Vec<bool>, Vec<Vec<(Grapheme, usize)>>) {
        let p = self.partition();
        let n = self.is_final.len();
        let mut cls_of = vec![0usize; n];
        for (i, class) in p.iter().enumerate() {
            for s in class {
                cls_of[*s] = i;
            }
        }
        // new node ids in order of first encounter while iterating old states
        let mut new_id: Vec<Option<usize>> = vec![None; p.len()];
        let mut new_final: Vec<bool> = Vec::new();
        let mut new_edges: Vec<Vec<(Grapheme, usize)>> = Vec::new();
        for s in 0..n {
            let c = cls_of[s];
            if new_id[c].is_none() {
                new_id[c] = Some(new_final.len());
                new_final.push(p[c].iter().any(|t| self.is_final[*t]));
                new_edges.push(vec![]);
            }
        }
        for s in 0..n {
            for (label, t) in self.edges[s].iter().rev() {
                let u = new_id[cls_of[s]].unwrap();
                let v = new_id[cls_of[*t]].unwrap();
                if !new_edges[u].iter().any(|(l, w)| l == label && *w == v) {
                    new_edges[u].push((label.clone(), v));
                }
            }
        }
        let start = new_id[cls_of[0]].unwrap();
        let mut order: Vec<usize> = Vec::new();
        let mut stack: Vec<usize> = vec![start];
        // depth first search in insertion order of the new edges
        fn dfs(u: usize, new_edges: &Vec<Vec<(Grapheme, usize)>>, order: &mut Vec<usize>) {
            if order.contains(&u) {
                return;
            }
            order.push(u);
            for (_, v) in &new_edges[u] {
                dfs(*v, new_edges, order);
            }
        }
        while let Some(u) = stack.pop() {
            dfs(u, &new_edges, &mut order);
        }
        let mut pos = vec![0usize; new_final.len()];
        for (i, u) in order.iter().enumerate() {
            pos[*u] = i;
        }
        let finals: Vec<bool> = order.iter().map(|u| new_final[*u]).collect();
        let edges: Vec<Vec<(Grapheme, usize)>> = order
            .iter()
            .map(|u| {
                new_edges[*u]
                    .iter()
                    .rev()
                    .map(|(l, v)| (l.clone(), pos[*v]))
                    .collect()
            })
            .collect();
        (finals, edges)
    }

    pub fn to_regex(&self) -> Option<Expr> {
        let (finals, edges) = self.minimize();
        let m = finals.len();
        let mut a: Vec<Vec<Option<Expr>>> = vec![vec![None; m]; m];
        let mut b: Vec<Option<Expr>> = vec![None; m];
        for i in 0..m {
            if finals[i] {
                b[i] = Some(Expr::Lit(vec![]));
            }
            for (label, j) in &edges[i] {
                let cur = a[i][*j].take();
                a[i][*j] = union(cur, Some(lit(label.clone())), Ctx::Labels);
            }
        }
        for n in (1..m).rev() {
            for i in 0..n {
                if a[i][n].is_some() {
                    let ain = a[i][n].clone();
                    let bn = b[n].clone();
                    let cur = b[i].take();
                    b[i] = union(cur, concat_opt(&ain, &bn), Ctx::Vector);
                    for j in 0..n {
                        let anj = a[n][j].clone();
                        let cur = a[i][j].take();
                        a[i][j] = union(cur, concat_opt(&ain, &anj), Ctx::Matrix);
                    }
                }
            }
        }
        b[0].take()
    }
}
