//! Rendering of expressions as strings, optionally in verbose mode and/or colorized.

use crate::expression::Expr;
use crate::grapheme::{escape_char, escape_class_char, Grapheme, Unit};
use std::collections::BTreeSet;

#[derive(Clone, Copy)]
pub struct Style {
    pub verbose: bool,
    pub colorize: bool,
    pub capturing: bool,
}

const RESET: &str = "\x1b[0m";

fn paint(s: &str, code: &str, style: &Style) -> String {
    if style.colorize {
        format!("\x1b[{}m{}{}", code, s, RESET)
    } else {
        s.to_string()
    }
}

pub fn anchor(s: &str, style: &Style) -> String {
    paint(s, "1;33", style)
}

pub fn flags(s: &str, style: &Style) -> String {
    paint(s, "40;93", style)
}

fn group_open(style: &Style) -> String {
    paint(if style.capturing { "(" } else { "(?:" }, "1;32", style)
}

fn group_close(style: &Style) -> String {
    paint(")", "1;32", style)
}

fn pipe(style: &Style) -> String {
    paint("|", "1;31", style)
}

fn question(style: &Style) -> String {
    paint("?", "1;35", style)
}

fn quantifier(g: &Grapheme, style: &Style) -> String {
    paint(&g.quantifier(), "104;37", style)
}

fn class_bracket(s: &str, style: &Style) -> String {
    paint(s, "1;36", style)
}

fn unit_str(u: &Unit, style: &Style) -> String {
    match u {
        Unit::Char(c) => {
            let mut s = String::new();
            escape_char(*c, style.verbose, &mut s);
            s
        }
        Unit::Class(s) => paint(s, "103;30", style),
        Unit::Escaped(s) => s.clone(),
    }
}

/// Inline rendering of a grapheme (used in non-verbose mode and for simple graphemes).
fn grapheme_str(g: &Grapheme, style: &Style) -> String {
    let mut s = String::new();
    if g.reps.is_empty() {
        for u in &g.units {
            s.push_str(&unit_str(u, style));
        }
    } else {
        for r in &g.reps {
            s.push_str(&grapheme_str(r, style));
        }
    }
    if g.has_quantifier() {
        if g.needs_group() {
            s = format!("{}{}{}", group_open(style), s, group_close(style));
        }
        s.push_str(&quantifier(g, style));
    }
    s
}

pub fn class_str(set: &BTreeSet<char>, style: &Style) -> String {
    let cs: Vec<char> = set.iter().cloned().collect();
    let mut body = String::new();
    let mut i = 0;
    while i < cs.len() {
        let mut j = i;
        while j + 1 < cs.len() && (cs[j + 1] as u32) == (cs[j] as u32) + 1 {
            j += 1;
        }
        if j - i >= 2 {
            escape_class_char(cs[i], style.verbose, &mut body);
            body.push('-');
            escape_class_char(cs[j], style.verbose, &mut body);
        } else {
            for c in &cs[i..=j] {
                escape_class_char(*c, style.verbose, &mut body);
            }
        }
        i = j + 1;
    }
    format!("{}{}{}", class_bracket("[", style), body, class_bracket("]", style))
}

/// Whether a quantifier applied to this expression requires a group.
fn needs_group(e: &Expr) -> bool {
    match e {
        Expr::Lit(gs) => gs.len() != 1 || gs[0].needs_group() || gs[0].has_quantifier(),
        Expr::Cat(_, _) => true,
        Expr::Alt(_) => false,
        Expr::Class(_) => false,
        Expr::Rep(_) => true,
    }
}

pub fn to_string(e: &Expr, style: &Style) -> String {
    match e {
        Expr::Lit(gs) => gs.iter().map(|g| grapheme_str(g, style)).collect(),
        Expr::Class(set) => class_str(set, style),
        Expr::Alt(opts) => {
            let inner: Vec<String> = opts.iter().map(|o| to_string(o, style)).collect();
            format!(
                "{}{}{}",
                group_open(style),
                inner.join(&pipe(style)),
                group_close(style)
            )
        }
        Expr::Cat(a, b) => format!("{}{}", to_string(a, style), to_string(b, style)),
        Expr::Rep(inner) => {
            let s = to_string(inner, style);
            if needs_group(inner) {
                format!("{}{}{}{}", group_open(style), s, group_close(style), question(style))
            } else {
                format!("{}{}", s, question(style))
            }
        }
    }
}

// ---------------------------------------------------------------------------------
// verbose mode

struct Lines {
    lines: Vec<String>,
}

impl Lines {
    fn push(&mut self, indent: usize, s: String) {
        self.lines.push(format!("{}{}", " ".repeat(indent), s));
    }
    fn append_to_last(&mut self, s: &str) {
        if let Some(last) = self.lines.last_mut() {
            last.push_str(s);
        }
    }
}

fn verbose_graphemes(gs: &[Grapheme], indent: usize, out: &mut Lines, style: &Style) {
    let mut line = String::new();
    for g in gs {
        if g.has_quantifier() && g.needs_group() {
            if !line.is_empty() {
                out.push(indent, std::mem::take(&mut line));
            }
            out.push(indent, group_open(style));
            if g.reps.is_empty() {
                let mut inner = String::new();
                for u in &g.units {
                    inner.push_str(&unit_str(u, style));
                }
                out.push(indent + 2, inner);
            } else {
                verbose_graphemes(&g.reps, indent + 2, out, style);
            }
            out.push(indent, format!("{}{}", group_close(style), quantifier(g, style)));
        } else {
            line.push_str(&grapheme_str(g, style));
        }
    }
    if !line.is_empty() {
        out.push(indent, line);
    }
}

fn verbose(e: &Expr, indent: usize, out: &mut Lines, style: &Style) {
    match e {
        Expr::Lit(gs) => verbose_graphemes(gs, indent, out, style),
        Expr::Class(set) => out.push(indent, class_str(set, style)),
        Expr::Alt(opts) => {
            out.push(indent, group_open(style));
            for (i, o) in opts.iter().enumerate() {
                if i > 0 {
                    out.push(indent + 2, pipe(style));
                }
                verbose(o, indent + 2, out, style);
            }
            out.push(indent, group_close(style));
        }
        Expr::Cat(a, b) => {
            verbose(a, indent, out, style);
            verbose(b, indent, out, style);
        }
        Expr::Rep(inner) => {
            if needs_group(inner) {
                out.push(indent, group_open(style));
                verbose(inner, indent + 2, out, style);
                out.push(indent, format!("{}{}", group_close(style), question(style)));
            } else {
                verbose(inner, indent, out, style);
                out.append_to_last(&question(style));
            }
        }
    }
}

pub fn to_verbose_lines(e: &Expr, indent: usize, style: &Style) -> Vec<String> {
    let mut out = Lines { lines: vec![] };
    verbose(e, indent, &mut out, style);
    out.lines
}
EOF
